/*
 * descarga — simulated download of a constancia. The real PDF is generated by the backend
 * (out of scope here), so the file is a printable HTML page with the same content: letterhead,
 * the rendered text and the signature. Covers: RF-32 (download when the peer asks for it).
 */
import { descargarTexto } from '@/lib/descarga'
import type { VistaConstancia } from '@/types/constancia'

function escapar(texto: string): string {
  return texto
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

export function htmlConstancia(vista: VistaConstancia): string {
  const parrafos = vista.cuerpo
    .split('\n\n')
    .map((p) => `<p>${escapar(p)}</p>`)
    .join('\n')
  return `<!doctype html>
<html lang="es">
<head><meta charset="utf-8"><title>Constancia de participación</title></head>
<body style="font-family: Georgia, serif; max-width: 640px; margin: 64px auto; text-align: center">
<h1>${escapar(vista.universidad)}</h1>
<h2>${escapar(vista.revista)}</h2>
${parrafos}
<p><strong>${escapar(vista.firma)}</strong></p>
${vista.fondo ? `<p><small>Fondo: ${escapar(vista.fondo)}</small></p>` : ''}
</body>
</html>
`
}

export function nombreArchivo(par: string): string {
  const limpio = par
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase()
  return `constancia-${limpio}.html`
}

/** Starts the browser download of the rendered constancia. */
export function descargarConstancia(vista: VistaConstancia, par: string): void {
  descargarTexto(nombreArchivo(par), htmlConstancia(vista), 'text/html')
}
